CREATE TABLE crosstax.rule_sync_runs (
	id VARCHAR(36) NOT NULL,
	trigger_type VARCHAR(20) NOT NULL,
	status VARCHAR(20) DEFAULT 'RUNNING' NOT NULL,
	started_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
	finished_at TIMESTAMP WITH TIME ZONE,
	error_message TEXT,
	summary JSON NOT NULL,
	PRIMARY KEY (id),
	CHECK (trigger_type IN ('SCHEDULED', 'MANUAL')),
	CHECK (status IN ('RUNNING', 'SUCCEEDED', 'PARTIAL', 'FAILED')),
	CHECK ((status = 'RUNNING' AND finished_at IS NULL)
        OR (status <> 'RUNNING' AND finished_at IS NOT NULL)),
	CHECK (finished_at IS NULL OR finished_at >= started_at)
);

CREATE INDEX ix_rule_sync_runs_started ON crosstax.rule_sync_runs (started_at);

CREATE TABLE crosstax.rule_versions (
	version_id VARCHAR(64) NOT NULL,
	schema_version INTEGER DEFAULT 1 NOT NULL,
	rules JSON NOT NULL,
	status VARCHAR(20) DEFAULT 'CANDIDATE' NOT NULL,
	validation_report JSON NOT NULL,
	extraction_metadata JSON NOT NULL,
	created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL,
	approved_at TIMESTAMP WITH TIME ZONE,
	PRIMARY KEY (version_id),
	CHECK (length(version_id) = 64),
	CHECK (schema_version > 0),
	CHECK (status IN ('CANDIDATE', 'APPROVED', 'REJECTED')),
	CHECK ((status = 'APPROVED' AND approved_at IS NOT NULL) OR (status <> 'APPROVED' AND approved_at IS NULL))
